//! The blocking bridge and I/O error mapping.

use std::future::Future;
use std::pin::pin;
use std::task::{Context, Poll, Waker};

use tinystoragedrivers_core::ErrorKind;

use super::*;

#[tokio::test]
async fn runs_on_the_blocking_pool_inside_a_runtime() {
    assert_eq!(run_blocking(|| Ok(7)).await.unwrap(), 7);
}

#[tokio::test]
async fn a_panicking_task_is_a_backend_error() {
    let error = run_blocking::<(), _>(|| panic!("boom")).await.unwrap_err();
    assert_eq!(error.kind(), ErrorKind::Backend);
}

#[test]
fn runs_inline_outside_a_runtime() {
    let mut future = pin!(run_blocking(|| Ok("inline")));
    let mut cx = Context::from_waker(Waker::noop());
    match future.as_mut().poll(&mut cx) {
        Poll::Ready(value) => assert_eq!(value.unwrap(), "inline"),
        Poll::Pending => panic!("inline work must complete on the first poll"),
    }
}

#[test]
fn transient_io_errors_are_unavailable() {
    for kind in [
        std::io::ErrorKind::WouldBlock,
        std::io::ErrorKind::Interrupted,
        std::io::ErrorKind::TimedOut,
    ] {
        let error = io_error("read", std::io::Error::from(kind));
        assert_eq!(error.kind(), ErrorKind::Unavailable);
        assert!(error.is_retryable());
    }
    let error = io_error(
        "read secrets",
        std::io::Error::from(std::io::ErrorKind::NotFound),
    );
    assert_eq!(error.kind(), ErrorKind::Backend);
    assert_eq!(error.message(), "could not read secrets");
    assert!(std::error::Error::source(&error).is_some());
}

//! The document driver on the core memory backend.

use serde_json::json;
use tinystoragedrivers_core::{ErrorKind, MemoryStorage, StorageBackend};

use super::*;
use crate::crypto::tests::{OPENHUMAN_ENC2, fixture_key};
use crate::keys::{DerivedKeys, StaticKey};
use crate::testkit::secrets_conformance;

fn derived() -> Arc<dyn KeyProvider> {
    Arc::new(DerivedKeys::new(crypto::generate_key().unwrap()))
}

#[tokio::test]
async fn passes_the_secrets_conformance_suite() {
    let storage = MemoryStorage::new().for_scope(&Scope::local()).unwrap();
    let store = DocumentSecrets::new(&storage, derived());
    secrets_conformance(&store).await;
    assert_eq!(store.backend_name(), "document");
}

#[tokio::test]
async fn stores_only_enc2_ciphertext_in_the_document() {
    let storage = MemoryStorage::new().for_scope(&Scope::local()).unwrap();
    let store = DocumentSecrets::new(&storage, derived());
    store.set("api_key", b"sk-live-abc").await.unwrap();
    let doc = storage
        .documents()
        .get(DEFAULT_COLLECTION, "api_key")
        .await
        .unwrap()
        .unwrap()
        .doc;
    let ciphertext = doc["ciphertext"].as_str().unwrap();
    assert!(crypto::is_enc2(ciphertext));
    assert!(!doc.to_string().contains("sk-live"));
    assert_eq!(doc.as_object().unwrap().len(), 1);
}

#[tokio::test]
async fn reads_an_enc2_value_openhuman_wrote() {
    let storage = MemoryStorage::new().for_scope(&Scope::local()).unwrap();
    storage
        .documents()
        .put(
            DEFAULT_COLLECTION,
            "migrated",
            json!({ "ciphertext": OPENHUMAN_ENC2 }),
            Precondition::Absent,
        )
        .await
        .unwrap();
    let store = DocumentSecrets::new(&storage, Arc::new(StaticKey::new(fixture_key())));
    assert_eq!(
        store.get("migrated").await.unwrap().unwrap().as_slice(),
        b"sk-test-123"
    );
}

#[tokio::test]
async fn binary_values_round_trip() {
    let storage = MemoryStorage::new().for_scope(&Scope::local()).unwrap();
    let store = DocumentSecrets::new(&storage, derived());
    store.set("bin", &[0, 0xff, 0x80]).await.unwrap();
    assert_eq!(
        store.get("bin").await.unwrap().unwrap().as_slice(),
        [0, 0xff, 0x80]
    );
}

#[tokio::test]
async fn tenants_get_distinct_keys_and_cannot_read_each_other() {
    let backend = MemoryStorage::new();
    let keys = derived();
    let a = DocumentSecrets::new(
        &backend.for_scope(&Scope::new("a").unwrap()).unwrap(),
        Arc::clone(&keys),
    );
    let b_storage = backend.for_scope(&Scope::new("b").unwrap()).unwrap();
    let b = DocumentSecrets::new(&b_storage, Arc::clone(&keys));
    a.set("shared-name", b"for-a").await.unwrap();
    assert!(b.get("shared-name").await.unwrap().is_none());

    // Even a ciphertext copied across tenants does not decrypt under the
    // other tenant's derived key.
    let a_doc = backend
        .for_scope(&Scope::new("a").unwrap())
        .unwrap()
        .documents()
        .get(DEFAULT_COLLECTION, "shared-name")
        .await
        .unwrap()
        .unwrap()
        .doc;
    b_storage
        .documents()
        .put(DEFAULT_COLLECTION, "shared-name", a_doc, Precondition::None)
        .await
        .unwrap();
    assert_eq!(
        b.get("shared-name").await.unwrap_err().kind(),
        ErrorKind::Crypto
    );
}

#[tokio::test]
async fn a_malformed_document_is_a_serialization_error() {
    let storage = MemoryStorage::new().for_scope(&Scope::local()).unwrap();
    storage
        .documents()
        .put(
            DEFAULT_COLLECTION,
            "bad",
            json!({ "ciphertext": 7 }),
            Precondition::None,
        )
        .await
        .unwrap();
    let store = DocumentSecrets::new(&storage, derived());
    assert_eq!(
        store.get("bad").await.unwrap_err().kind(),
        ErrorKind::Serialization
    );
}

#[tokio::test]
async fn a_custom_collection_is_used_and_validated() {
    let storage = MemoryStorage::new().for_scope(&Scope::local()).unwrap();
    let store =
        DocumentSecrets::from_parts(Arc::clone(storage.documents()), Scope::local(), derived())
            .with_collection("vault")
            .unwrap();
    assert_eq!(store.collection(), "vault");
    assert_eq!(store.scope(), &Scope::local());
    store.set("a", b"1").await.unwrap();
    assert!(
        storage
            .documents()
            .get("vault", "a")
            .await
            .unwrap()
            .is_some()
    );

    let error = store.clone().with_collection("bad name").unwrap_err();
    assert_eq!(error.kind(), ErrorKind::InvalidInput);
}

#[test]
fn debug_names_scope_and_collection_only() {
    let storage = MemoryStorage::new().for_scope(&Scope::local()).unwrap();
    let store = DocumentSecrets::new(&storage, Arc::new(StaticKey::new(fixture_key())));
    let debug = format!("{store:?}");
    assert!(debug.contains("local") && debug.contains("secrets"));
    assert!(!debug.contains("0001020304"));
}

/// A provider whose key source is down.
#[derive(Debug)]
struct Outage;

impl KeyProvider for Outage {
    fn data_key(&self, _scope: &Scope) -> Result<Zeroizing<[u8; crypto::KEY_LEN]>> {
        Err(StorageError::unavailable("kms unreachable"))
    }
}

#[tokio::test]
async fn a_key_provider_failure_propagates() {
    let storage = MemoryStorage::new().for_scope(&Scope::local()).unwrap();
    let store = DocumentSecrets::new(&storage, Arc::new(Outage));
    assert_eq!(
        store.set("a", b"1").await.unwrap_err().kind(),
        ErrorKind::Unavailable
    );
    storage
        .documents()
        .put(
            DEFAULT_COLLECTION,
            "a",
            json!({ "ciphertext": "enc2:00" }),
            Precondition::None,
        )
        .await
        .unwrap();
    assert_eq!(
        store.get("a").await.unwrap_err().kind(),
        ErrorKind::Unavailable
    );
}

//! The memory driver against the conformance suite, plus binary values.

use super::*;
use crate::testkit::secrets_conformance;

#[tokio::test]
async fn passes_the_secrets_conformance_suite() {
    let store = MemorySecrets::new();
    secrets_conformance(&store).await;
    assert_eq!(store.backend_name(), "memory");
}

#[tokio::test]
async fn holds_binary_values_and_redacts_debug() {
    let store = MemorySecrets::new();
    store.set("bin", &[0, 0xff, 0x80]).await.unwrap();
    assert_eq!(
        store.get("bin").await.unwrap().unwrap().as_slice(),
        [0, 0xff, 0x80]
    );
    assert_eq!(format!("{store:?}"), "MemorySecrets { len: 1 }");
}

#[test]
fn a_poisoned_lock_is_recovered() {
    let store = std::sync::Arc::new(MemorySecrets::new());
    let clone = std::sync::Arc::clone(&store);
    let _ = std::thread::spawn(move || {
        let _guard = clone.entries();
        panic!("poison the lock");
    })
    .join();
    assert!(store.entries().is_empty());
}

//! Name and prefix validation.

use tinystoragedrivers_core::ErrorKind;

use super::*;

#[test]
fn accepts_namespaced_printable_names() {
    validate_name("alice:openai_api_key").unwrap();
    validate_name("with space and ünïcode").unwrap();
    validate_name(&"x".repeat(MAX_SECRET_NAME_LEN)).unwrap();
}

#[test]
fn rejects_empty_long_and_control_names() {
    for bad in [
        String::new(),
        "x".repeat(MAX_SECRET_NAME_LEN + 1),
        "nul\0byte".to_string(),
        "new\nline".to_string(),
    ] {
        let error = validate_name(&bad).unwrap_err();
        assert_eq!(error.kind(), ErrorKind::InvalidInput);
    }
}

#[test]
fn error_messages_never_repeat_the_name() {
    let error = validate_name("sk-live\0secret").unwrap_err();
    assert!(!error.to_string().contains("sk-live"));
}

#[test]
fn prefixes_may_be_empty_but_not_long_or_control() {
    validate_prefix("").unwrap();
    validate_prefix("alice:").unwrap();
    assert_eq!(
        validate_prefix(&"x".repeat(MAX_SECRET_NAME_LEN + 1))
            .unwrap_err()
            .kind(),
        ErrorKind::InvalidInput
    );
    assert_eq!(
        validate_prefix("a\0").unwrap_err().kind(),
        ErrorKind::InvalidInput
    );
}

#[test]
fn require_utf8_rejects_binary_without_echoing_it() {
    assert_eq!(require_utf8(b"text", "file").unwrap(), "text");
    let error = require_utf8(&[0xff, 0xfe], "file").unwrap_err();
    assert_eq!(error.kind(), ErrorKind::InvalidInput);
    assert!(error.to_string().contains("file"));
}

//! The suite catches a store that breaks the contract.

use async_trait::async_trait;
use tinystoragedrivers_core::{Result, StorageError};
use zeroize::Zeroizing;

use super::*;
use crate::MemorySecrets;

/// A memory store that claims it cannot enumerate, to drive the
/// non-enumerable branch.
#[derive(Debug, Default)]
struct Opaque(MemorySecrets);

#[async_trait]
impl SecretStore for Opaque {
    async fn get(&self, name: &str) -> Result<Option<Zeroizing<Vec<u8>>>> {
        self.0.get(name).await
    }
    async fn set(&self, name: &str, value: &[u8]) -> Result<()> {
        self.0.set(name, value).await
    }
    async fn delete(&self, name: &str) -> Result<bool> {
        self.0.delete(name).await
    }
    async fn list(&self, prefix: &str) -> Result<Vec<String>> {
        crate::store::validate_prefix(prefix)?;
        Err(StorageError::backend("cannot enumerate"))
    }
    fn enumerable(&self) -> bool {
        false
    }
    fn backend_name(&self) -> &'static str {
        "opaque"
    }
}

#[tokio::test]
async fn a_non_enumerable_store_passes_when_list_fails_with_backend() {
    secrets_conformance(&Opaque::default()).await;
}

#[tokio::test]
#[should_panic(expected = "a store that cannot enumerate must say so")]
async fn a_non_enumerable_store_with_the_wrong_list_error_fails() {
    #[derive(Debug, Default)]
    struct WrongKind(Opaque);
    #[async_trait]
    impl SecretStore for WrongKind {
        async fn get(&self, name: &str) -> Result<Option<Zeroizing<Vec<u8>>>> {
            self.0.get(name).await
        }
        async fn set(&self, name: &str, value: &[u8]) -> Result<()> {
            self.0.set(name, value).await
        }
        async fn delete(&self, name: &str) -> Result<bool> {
            self.0.delete(name).await
        }
        async fn list(&self, _prefix: &str) -> Result<Vec<String>> {
            Err(StorageError::invalid_input("wrong kind"))
        }
        fn enumerable(&self) -> bool {
            false
        }
        fn backend_name(&self) -> &'static str {
            "wrong"
        }
    }
    secrets_conformance(&WrongKind::default()).await;
}

/// A store that drops every overwrite, so the suite fails part way.
#[derive(Debug, Default)]
struct ForgetsOverwrites(MemorySecrets);

#[async_trait]
impl SecretStore for ForgetsOverwrites {
    async fn get(&self, name: &str) -> Result<Option<Zeroizing<Vec<u8>>>> {
        self.0.get(name).await
    }
    async fn set(&self, name: &str, value: &[u8]) -> Result<()> {
        if self.0.get(name).await?.is_none() {
            self.0.set(name, value).await?;
        }
        Ok(())
    }
    async fn delete(&self, name: &str) -> Result<bool> {
        self.0.delete(name).await
    }
    async fn list(&self, prefix: &str) -> Result<Vec<String>> {
        self.0.list(prefix).await
    }
    fn backend_name(&self) -> &'static str {
        "forgetful"
    }
}

#[tokio::test]
async fn a_failed_check_still_removes_what_the_suite_wrote() {
    let store = ForgetsOverwrites::default();
    let outcome = CatchUnwind(Box::pin(secrets_conformance(&store))).await;
    assert!(outcome.is_err(), "the overwrite check must fail");
    assert_eq!(store.0.list("").await.unwrap(), Vec::<String>::new());
}

#[test]
fn prefixes_are_unique_per_call() {
    assert_ne!(unique_prefix(), unique_prefix());
}

//! Static and derived key providers.

use tinystoragedrivers_core::ErrorKind;

use super::*;
use crate::crypto::key_to_hex;

const MASTER_HEX: &str = "000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f";

#[test]
fn a_static_key_is_the_same_for_every_scope() {
    let provider = StaticKey::from_hex(MASTER_HEX).unwrap();
    let a = provider.data_key(&Scope::local()).unwrap();
    let b = provider.data_key(&Scope::new("tenant-b").unwrap()).unwrap();
    assert_eq!(*a, *b);
    assert_eq!(key_to_hex(&a).as_str(), MASTER_HEX);
}

#[test]
fn derived_keys_differ_per_scope_and_from_the_master() {
    let provider = DerivedKeys::from_hex(MASTER_HEX).unwrap();
    let a = provider.data_key(&Scope::new("tenant-a").unwrap()).unwrap();
    let b = provider.data_key(&Scope::new("tenant-b").unwrap()).unwrap();
    assert_ne!(*a, *b);
    assert_ne!(key_to_hex(&a).as_str(), MASTER_HEX);
    // Deterministic: the same scope always gets the same key.
    let again = provider.data_key(&Scope::new("tenant-a").unwrap()).unwrap();
    assert_eq!(*a, *again);
}

#[test]
fn derivation_is_pinned_to_hkdf_sha256_with_the_v1_label() {
    // Pinned so a refactor cannot silently re-key every tenant.
    let provider = DerivedKeys::from_hex(MASTER_HEX).unwrap();
    let key = provider.data_key(&Scope::local()).unwrap();
    let hkdf = Hkdf::<Sha256>::new(None, &key_from_hex(MASTER_HEX).unwrap()[..]);
    let mut expected = [0u8; KEY_LEN];
    hkdf.expand(b"tinystoragedrivers-secrets/v1:local", &mut expected)
        .unwrap();
    assert_eq!(*key, expected);
}

#[test]
fn bad_hex_is_a_crypto_error() {
    assert_eq!(
        StaticKey::from_hex("abc").unwrap_err().kind(),
        ErrorKind::Crypto
    );
    assert_eq!(
        DerivedKeys::from_hex("00").unwrap_err().kind(),
        ErrorKind::Crypto
    );
}

#[test]
fn debug_never_prints_key_material() {
    let static_key = StaticKey::from_hex(MASTER_HEX).unwrap();
    let derived = DerivedKeys::from_hex(MASTER_HEX).unwrap();
    assert_eq!(format!("{static_key:?}"), "StaticKey(..)");
    assert_eq!(format!("{derived:?}"), "DerivedKeys(..)");
}

//! The keyring driver over an in-memory credential builder (never the real OS
//! store), the error mapping, and the opt-in `live_*` test.

use std::any::Any;
use std::collections::HashMap;
use std::sync::Mutex;

use keyring::credential::{Credential, CredentialApi, CredentialBuilderApi};
use tinystoragedrivers_core::ErrorKind;

use super::*;
use crate::crypto::tests::FIXTURE_KEY_HEX;
use crate::testkit::secrets_conformance;

type Shared = Arc<Mutex<HashMap<(String, String), Vec<u8>>>>;

/// What a [`FakeCredential`] does instead of storing.
#[derive(Clone, Copy, Debug, Default)]
enum Fault {
    #[default]
    None,
    /// Every call fails with `NoStorageAccess`.
    Locked,
    /// Writes are accepted but dropped, so a read-back finds nothing new.
    DropWrites,
    /// Writes store something other than what was written.
    CorruptWrites,
}

/// A credential store shared by every credential the builder makes, so a set
/// through one `Entry` is visible through the next, as on a real keychain.
#[derive(Debug, Default)]
struct FakeBuilder {
    store: Shared,
    fault: Fault,
}

#[derive(Debug)]
struct FakeCredential {
    store: Shared,
    id: (String, String),
    fault: Fault,
}

impl CredentialBuilderApi for FakeBuilder {
    fn build(
        &self,
        _target: Option<&str>,
        service: &str,
        user: &str,
    ) -> keyring::Result<Box<Credential>> {
        if user.len() > 200 {
            return Err(keyring::Error::TooLong("user".to_string(), 200));
        }
        Ok(Box::new(FakeCredential {
            store: Arc::clone(&self.store),
            id: (service.to_string(), user.to_string()),
            fault: self.fault,
        }))
    }

    fn as_any(&self) -> &dyn Any {
        self
    }
}

fn locked() -> keyring::Error {
    keyring::Error::NoStorageAccess(Box::new(std::io::Error::other("locked")))
}

impl CredentialApi for FakeCredential {
    fn set_secret(&self, secret: &[u8]) -> keyring::Result<()> {
        let stored = match self.fault {
            Fault::Locked => return Err(locked()),
            Fault::DropWrites => return Ok(()),
            Fault::CorruptWrites => b"something else".to_vec(),
            Fault::None => secret.to_vec(),
        };
        self.store.lock().unwrap().insert(self.id.clone(), stored);
        Ok(())
    }

    fn get_secret(&self) -> keyring::Result<Vec<u8>> {
        if let Fault::Locked = self.fault {
            return Err(locked());
        }
        self.store
            .lock()
            .unwrap()
            .get(&self.id)
            .cloned()
            .ok_or(keyring::Error::NoEntry)
    }

    fn delete_credential(&self) -> keyring::Result<()> {
        if let Fault::Locked = self.fault {
            return Err(locked());
        }
        self.store
            .lock()
            .unwrap()
            .remove(&self.id)
            .map(|_| ())
            .ok_or(keyring::Error::NoEntry)
    }

    fn as_any(&self) -> &dyn Any {
        self
    }
}

fn fake(fault: Fault) -> (KeyringSecrets, Shared) {
    let builder = FakeBuilder {
        fault,
        ..FakeBuilder::default()
    };
    let store = Arc::clone(&builder.store);
    (
        KeyringSecrets::with_credential_builder("tsd-test", Box::new(builder)),
        store,
    )
}

#[tokio::test]
async fn passes_the_secrets_conformance_suite() {
    let (secrets, _) = fake(Fault::None);
    secrets_conformance(&secrets).await;
    assert_eq!(secrets.backend_name(), "keyring");
    assert!(!secrets.enumerable());
    assert_eq!(secrets.service(), "tsd-test");
}

#[tokio::test]
async fn stores_one_password_per_name_under_the_service() {
    let (secrets, store) = fake(Fault::None);
    secrets.set("alice:api_key", b"sk-live-abc").await.unwrap();
    let stored = store.lock().unwrap().clone();
    assert_eq!(
        stored[&("tsd-test".to_string(), "alice:api_key".to_string())],
        b"sk-live-abc"
    );
}

#[tokio::test]
async fn reads_an_entry_written_in_openhumans_layout() {
    let (secrets, store) = fake(Fault::None);
    store.lock().unwrap().insert(
        ("tsd-test".to_string(), "alice:oauth".to_string()),
        "tok-\u{e9}".as_bytes().to_vec(),
    );
    assert_eq!(
        secrets
            .get("alice:oauth")
            .await
            .unwrap()
            .unwrap()
            .as_slice(),
        "tok-\u{e9}".as_bytes()
    );
}

#[tokio::test]
async fn binary_values_and_listing_are_refused() {
    let (secrets, _) = fake(Fault::None);
    assert_eq!(
        secrets.set("bin", &[0xff]).await.unwrap_err().kind(),
        ErrorKind::InvalidInput
    );
    assert_eq!(
        secrets.list("x").await.unwrap_err().kind(),
        ErrorKind::Backend
    );
    assert_eq!(
        secrets.list("x\0").await.unwrap_err().kind(),
        ErrorKind::InvalidInput
    );
}

#[tokio::test]
async fn a_non_utf8_stored_value_is_a_serialization_error() {
    let (secrets, store) = fake(Fault::None);
    store.lock().unwrap().insert(
        ("tsd-test".to_string(), "raw".to_string()),
        vec![0xff, 0xfe],
    );
    assert_eq!(
        secrets.get("raw").await.unwrap_err().kind(),
        ErrorKind::Serialization
    );
}

#[tokio::test]
async fn a_locked_store_is_unavailable_everywhere() {
    let (secrets, _) = fake(Fault::Locked);
    assert_eq!(
        secrets.get("a").await.unwrap_err().kind(),
        ErrorKind::Unavailable
    );
    assert_eq!(
        secrets.set("a", b"1").await.unwrap_err().kind(),
        ErrorKind::Unavailable
    );
    assert_eq!(
        secrets.delete("a").await.unwrap_err().kind(),
        ErrorKind::Unavailable
    );
}

#[tokio::test]
async fn a_name_the_platform_rejects_is_invalid_input() {
    let (secrets, _) = fake(Fault::None);
    let name = "n".repeat(201);
    assert_eq!(
        secrets.get(&name).await.unwrap_err().kind(),
        ErrorKind::InvalidInput
    );
}

#[tokio::test]
async fn load_or_create_key_creates_once_then_reuses() {
    let (secrets, store) = fake(Fault::None);
    let first = secrets.load_or_create_key("app:master_key").await.unwrap();
    let stored =
        store.lock().unwrap()[&("tsd-test".to_string(), "app:master_key".to_string())].clone();
    assert_eq!(String::from_utf8(stored).unwrap(), *key_to_hex(&first));
    let second = secrets.load_or_create_key("app:master_key").await.unwrap();
    assert_eq!(*first, *second);
}

#[tokio::test(flavor = "multi_thread", worker_threads = 4)]
async fn concurrent_key_creation_agrees_on_one_key() {
    let (secrets, _) = fake(Fault::None);
    let tasks: Vec<_> = (0..16)
        .map(|_| {
            let secrets = secrets.clone();
            tokio::spawn(async move { secrets.load_or_create_key("app:race").await.unwrap() })
        })
        .collect();
    let mut keys = Vec::new();
    for task in tasks {
        keys.push(*task.await.unwrap());
    }
    assert!(keys.windows(2).all(|pair| pair[0] == pair[1]));
}

